void AAlsCharacter::Tick(const float DeltaTime)
{
	DECLARE_SCOPE_CYCLE_COUNTER(TEXT("AAlsCharacter::Tick"), STAT_AAlsCharacter_Tick, STATGROUP_Als)
	TRACE_CPUPROFILER_EVENT_SCOPE_STR(__FUNCTION__)

	if (!IsValid(Settings) || !AnimationInstance.IsValid())
	{
		Super::Tick(DeltaTime);
		return;
	}

	RefreshMovementBase();

	RefreshMeshProperties();

	RefreshInput(DeltaTime);

	RefreshLocomotionEarly();

	RefreshView(DeltaTime);
	RefreshLocomotion();
	RefreshGait();
	RefreshRotationMode();

	RefreshRotation(DeltaTime);

	AutoStartMantling();
	RefreshMantling();
	RefreshRagdolling(DeltaTime);
	RefreshRolling(DeltaTime);

	Super::Tick(DeltaTime);

	RefreshLocomotionLate();
}

void AAlsCharacter::RefreshLocomotion()
{
	const auto bHadVelocity{LocomotionState.bHasVelocity};

	LocomotionState.Velocity = GetVelocity();

	// Determine if the character is moving by getting its speed. The speed equals the length
	// of the horizontal velocity, so it does not take vertical movement into account. If the
	// character is moving, update the last velocity rotation. This value is saved because it might
	// be useful to know the last orientation of a movement even after the character has stopped.

	LocomotionState.Speed = UE_REAL_TO_FLOAT(LocomotionState.Velocity.Size2D());

	static constexpr auto HasSpeedThreshold{1.0f};

	LocomotionState.bHasVelocity = LocomotionState.Speed >= HasSpeedThreshold;

	if (LocomotionState.bHasVelocity)
	{
		LocomotionState.VelocityYawAngle = UE_REAL_TO_FLOAT(UAlsVector::DirectionToAngleXY(LocomotionState.Velocity));
	}

	if (GetLocalRole() >= ROLE_AutonomousProxy)
	{
		auto bSendInitialVelocityYawAngle{LocomotionState.bHasVelocity && !bHadVelocity};
		auto VelocityYawAngleToSend{LocomotionState.VelocityYawAngle};

		if (Settings->bRotateTowardsDesiredVelocityInVelocityDirectionRotationMode)
		{
			FVector DesiredVelocity;
			if (AlsCharacterMovement->TryConsumePrePenetrationAdjustmentVelocity(DesiredVelocity) &&
			    DesiredVelocity.Size2D() >= HasSpeedThreshold)
			{
				bSendInitialVelocityYawAngle = !bHasDesiredVelocity;
				bHasDesiredVelocity = true;

				SetDesiredVelocityYawAngle(UE_REAL_TO_FLOAT(UAlsVector::DirectionToAngleXY(DesiredVelocity)));
			}
			else
			{
				bSendInitialVelocityYawAngle = LocomotionState.bHasVelocity && !bHasDesiredVelocity;
				bHasDesiredVelocity = LocomotionState.bHasVelocity;

				SetDesiredVelocityYawAngle(LocomotionState.VelocityYawAngle);
			}

			VelocityYawAngleToSend = DesiredVelocityYawAngle;
		}

		// Implicitly send the initial velocity yaw angle from the owning client to other clients,
		// since VelocityYawAngle changes are not always detected on the server for very short moves.

		if (bSendInitialVelocityYawAngle &&
		    (GetLocalRole() == ROLE_AutonomousProxy ||
		     GetRemoteRole() == ROLE_SimulatedProxy ||
		     (IsNetMode(NM_ListenServer) && IsLocallyControlled())))
		{
			ServerSetInitialVelocityYawAngle(VelocityYawAngleToSend);
		}
	}

	// Character is moving if has speed and current acceleration, or if the speed is greater than the moving speed threshold.

	LocomotionState.bMoving = (LocomotionState.bHasInput && LocomotionState.bHasVelocity) ||
	                          LocomotionState.Speed > Settings->MovingSpeedThreshold;
}

void UAlsAnimationInstance::NativeUpdateAnimation(const float DeltaTime)
{
	DECLARE_SCOPE_CYCLE_COUNTER(TEXT("UAlsAnimationInstance::NativeUpdateAnimation"),
	                            STAT_UAlsAnimationInstance_NativeUpdateAnimation, STATGROUP_Als)
	TRACE_CPUPROFILER_EVENT_SCOPE_STR(__FUNCTION__)

	Super::NativeUpdateAnimation(DeltaTime);

	if (!IsValid(Settings) || !IsValid(Character))
	{
		return;
	}

	// Use the previous global time dilation because this frame's delta time may not yet be affected
	// by the current global time dilation, so unscaling it would produce an incorrect result.

	const auto TimeDilation{PreviousGlobalTimeDilation * Character->CustomTimeDilation};
	DeltaTimeWithoutTimeDilation = TimeDilation > UE_SMALL_NUMBER ? DeltaTime / TimeDilation : GetWorld()->DeltaRealTimeSeconds;
	PreviousGlobalTimeDilation = GetWorld()->GetWorldSettings()->GetEffectiveTimeDilation();

	auto* Mesh{GetSkelMeshComponent()};

	if (Mesh->IsUsingAbsoluteRotation() && IsValid(Mesh->GetAttachParent()))
	{
		const auto& ParentTransform{Mesh->GetAttachParent()->GetComponentTransform()};

		// Manually synchronize mesh rotation with character rotation.

		Mesh->SetRelativeRotation(ParentTransform.GetRotation() * Character->GetBaseRotationOffset());

		// Re-cache proxy transforms to match the modified mesh transform.

		const auto& Proxy{GetProxyOnGameThread<FAnimInstanceProxy>()};
		const_cast<FTransform&>(Proxy.GetComponentTransform()) = Mesh->GetComponentTransform();
		const_cast<FTransform&>(Proxy.GetComponentRelativeTransform()) = Mesh->GetRelativeTransform();
		const_cast<FTransform&>(Proxy.GetActorTransform()) = Character->GetActorTransform();
	}

#if WITH_EDITORONLY_DATA && ENABLE_DRAW_DEBUG
	bDisplayDebugTraces = UAlsDebugUtility::ShouldDisplayDebugForActor(Character, UAlsConstants::TracesDebugDisplayName());
#endif

	ViewMode = Character->GetViewMode();
	LocomotionMode = Character->GetLocomotionMode();
	RotationMode = Character->GetRotationMode();
	Stance = Character->GetStance();
	Gait = Character->GetGait();
	OverlayMode = Character->GetOverlayMode();

	if (LocomotionAction != Character->GetLocomotionAction())
	{
		LocomotionAction = Character->GetLocomotionAction();
		ResetGroundedEntryMode();
	}

	const auto PreviousLocation{LocomotionState.LocationWorldSpace};

	RefreshMovementBaseOnGameThread();
	RefreshViewOnGameThread();
	RefreshLocomotionOnGameThread();
	RefreshInAirOnGameThread();
	RefreshFeetOnGameThread();
	RefreshRagdollingOnGameThread();

	if (!bPendingUpdate && IsValid(Character->GetSettings()) &&
	    FVector::DistSquared(PreviousLocation, LocomotionState.LocationWorldSpace) >
	    FMath::Square(Character->GetSettings()->TeleportDistanceThreshold))
	{
		MarkTeleported();
	}
}

void UAlsAnimationInstance::RefreshLocomotionOnGameThread()
{
	check(IsInGameThread())

	const auto DeltaTime{GetDeltaSeconds()};
	const auto bCanCalculateRateOfChange{!bPendingUpdate && DeltaTime > UE_SMALL_NUMBER};

	const auto& Locomotion{Character->GetLocomotionState()};

	LocomotionState.bHasInput = Locomotion.bHasInput;
	LocomotionState.InputYawAngleWorldSpace = Locomotion.InputYawAngle;

	const auto PreviousVelocity{
		MovementBase.bHasRelativeRotation
			? MovementBase.DeltaRotation.RotateVector(LocomotionState.VelocityWorldSpace)
			: LocomotionState.VelocityWorldSpace
	};

	LocomotionState.Speed = Locomotion.Speed;
	LocomotionState.VelocityWorldSpace = Locomotion.Velocity;
	LocomotionState.VelocityYawAngleWorldSpace = Locomotion.VelocityYawAngle;

	LocomotionState.AccelerationWorldSpace = bCanCalculateRateOfChange
		                                         ? (LocomotionState.VelocityWorldSpace - PreviousVelocity) / DeltaTime
		                                         : FVector::ZeroVector;

	const auto* Movement{Character->GetCharacterMovement()};

	LocomotionState.MaxAcceleration = Movement->GetMaxAcceleration();
	LocomotionState.MaxBrakingDeceleration = Movement->GetMaxBrakingDeceleration();
	LocomotionState.WalkableFloorAngleCos = Movement->GetWalkableFloorZ();

	LocomotionState.bMoving = Locomotion.bMoving;

	LocomotionState.bMovingSmooth = (Locomotion.bHasInput && Locomotion.bHasVelocity) ||
	                                Locomotion.Speed > Settings->General.MovingSmoothSpeedThreshold;

	LocomotionState.TargetYawAngleWorldSpace = Locomotion.TargetYawAngle;

